From d12e4799a2455bd7a28691b03c6a7a87a68ed0ed Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:54:35 +0100
Subject: [PATCH] applet: add a search field to filter devices

With many paired devices, finding one meant scrolling and skimming the
whole list. A search field in the toolbar now filters the list by device
name or address, and shows a "No matches" message when nothing matches.

BUG: 516932
---
 src/applet/devicesproxymodel.cpp      |  7 +++++++
 src/applet/qml/FullRepresentation.qml | 17 +++++++++++++++--
 src/applet/qml/Toolbar.qml            |  8 +++++++-
 3 files changed, 29 insertions(+), 3 deletions(-)

diff --git a/src/applet/devicesproxymodel.cpp b/src/applet/devicesproxymodel.cpp
index bea49e5c..03d6ce13 100644
--- a/src/applet/devicesproxymodel.cpp
+++ b/src/applet/devicesproxymodel.cpp
@@ -16,6 +16,7 @@ DevicesProxyModel::DevicesProxyModel(QObject *parent)
     : QSortFilterProxyModel(parent)
 {
     setDynamicSortFilter(true);
+    setFilterCaseSensitivity(Qt::CaseInsensitive);
     sort(0, Qt::DescendingOrder);
 }

@@ -130,6 +131,12 @@ bool DevicesProxyModel::filterAcceptsRow(int source_row, const QModelIndex &sour
         return false;
     }

+    const QRegularExpression filter = filterRegularExpression();
+    if (!filter.pattern().isEmpty() && !index.data(BluezQt::DevicesModel::NameRole).toString().contains(filter)
+        && !index.data(BluezQt::DevicesModel::AddressRole).toString().contains(filter)) {
+        return false;
+    }
+
     if (m_unpairedOnly) {
         // The Bigscreen KCM has a seperate ListView for unpaired devices, because the wizard isn't used to pair
         return !index.data(BluezQt::DevicesModel::RemoteNameRole).toString().isEmpty() && !index.data(BluezQt::DevicesModel::PairedRole).toBool(); 
diff --git a/src/applet/qml/FullRepresentation.qml b/src/applet/qml/FullRepresentation.qml
index c281b129..edf28286 100644
--- a/src/applet/qml/FullRepresentation.qml
+++ b/src/applet/qml/FullRepresentation.qml
@@ -56,7 +56,7 @@ PlasmaExtras.Representation {
         if (listView.count === 0) {
             return;
         }
-        if (listView.currentIndex < 0 || toolbar.onSwitch.activeFocus) {
+        if (listView.currentIndex < 0 || toolbar.onSwitch.activeFocus || toolbar.searchField.activeFocus) {
             listView.incrementCurrentIndex();
             listView.currentItem.forceActiveFocus();
         } else {
@@ -94,6 +94,17 @@ PlasmaExtras.Representation {

         visible: BluezQt.Manager.adapters.length > 0
         focus: true
+
+        searchField.onTextChanged: devicesModel.setFilterFixedString(searchField.text)
+    }
+
+    Connections {
+        target: root.plasmoidItem
+        function onExpandedChanged() {
+            if (!root.plasmoidItem.expanded) {
+                toolbar.searchField.clear();
+            }
+        }
     }

     PlasmaComponents3.ScrollView {
@@ -145,7 +156,7 @@ PlasmaExtras.Representation {
             Loader {
                 anchors.centerIn: parent
                 width: parent.width - (4 * Kirigami.Units.gridUnit)
-                active: BluezQt.Manager.rfkill.state === BluezQt.Rfkill.Unknown || !BluezQt.Manager.bluetoothOperational || root.emptyList
+                active: BluezQt.Manager.rfkill.state === BluezQt.Rfkill.Unknown || !BluezQt.Manager.bluetoothOperational || root.emptyList || (listView.count === 0 && toolbar.searchField.text.length > 0)
                 sourceComponent: PlasmaExtras.PlaceholderMessage {
                     iconName: BluezQt.Manager.rfkill.state === BluezQt.Rfkill.Unknown || !BluezQt.Manager.bluetoothOperational ? "network-bluetooth" : "network-bluetooth-activated"

@@ -158,6 +169,8 @@ PlasmaExtras.Representation {
                             return i18n("Bluetooth is disabled");
                         } else if (root.emptyList) {
                             return i18n("No devices paired");
+                        } else if (listView.count === 0 && toolbar.searchField.text.length > 0) {
+                            return i18nc("@info:placeholder", "No matches");
                         } else {
                             return "";
                         }
diff --git a/src/applet/qml/Toolbar.qml b/src/applet/qml/Toolbar.qml
index ce3ecc9c..8f3add3b 100644
--- a/src/applet/qml/Toolbar.qml
+++ b/src/applet/qml/Toolbar.qml
@@ -28,6 +28,7 @@ PlasmaExtras.PlasmoidHeading {
     required property PlasmaCore.Action configureAction

     readonly property alias onSwitch: onSwitch
+    readonly property alias searchField: searchField

     leftPadding: mirrored ? 0 : Kirigami.Units.smallSpacing
     rightPadding: mirrored ? Kirigami.Units.smallSpacing : 0
@@ -43,10 +44,15 @@ PlasmaExtras.PlasmoidHeading {
             enabled: root.toggleBluetoothAction.visible
             focus: root.plasmoidItem.expanded
             onToggled: root.toggleBluetoothAction.trigger()
+            KeyNavigation.right: searchField
         }

-        Item {
+        PlasmaExtras.SearchField {
+            id: searchField
+
             Layout.fillWidth: true
+
+            enabled: (BluezQt.Manager.bluetoothOperational && BluezQt.Manager.devices.length > 0) || text.length > 0
         }

         PlasmaComponents3.ToolButton {
-- 
